def resolve(path, cwd, links):
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None
    if not isinstance(path, str):
        return None
    if not isinstance(links, dict):
        return None

    # Start with cwd if path is relative
    if path.startswith('/'):
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            # Move to parent
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            next_path = '/' + comp
        else:
            next_path = current + '/' + comp

        # Check if this path is a symlink
        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            # Get the link target
            target = links[next_path]

            # If target doesn't start with '/', it's relative to the directory containing the link
            if not target.startswith('/'):
                # Directory containing the link
                link_dir = next_path.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                # Make target absolute
                if link_dir == '/':
                    target = '/' + target
                else:
                    target = link_dir + '/' + target

            # Parse the target and insert its components at current position
            if target.startswith('/'):
                current = '/'
                target_components = target[1:].split('/')
            else:
                target_components = target.split('/')

            # Replace current component with target components
            components = components[:i] + target_components + components[i+1:]
            continue

        current = next_path
        i += 1

    # Remove trailing slash if not root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

